    macos: "42631635a7ad06b596231ecabdf8d605e5797650c11b19777ec44d50e0c36d58",
    linux: on_arch_conditional(
      arm:   "36fc12a096b3659530c6f65e7f579fa142c0407235c071979904500b7104a016",
